@font-face {
  font-family: "Press Start 2P";
  src: url("assets/fonts/PressStart2P.ttf") format("truetype");
  font-display: swap;
}

:root {
  --bg: #070810;
  --bg2: #0d0f1a;
  --panel: #121421;
  --panel2: #171a2a;
  --line: #2d3147;
  --line-soft: #202337;
  --text: #f4f3e9;
  --muted: #8e93ab;
  --lime: #d8ff3e;
  --lime-dark: #93b41a;
  --red: #ff5349;
  --cyan: #47e5ff;
  --yellow: #ffd23f;
  --green: #58d68d;
  --purple: #a887ff;
  --display: "Press Start 2P", "Courier New", monospace;
  --mono: "DejaVu Sans Mono", "Liberation Mono", "Courier New", monospace;
  --shadow: 5px 5px 0 rgba(0, 0, 0, 0.55);
  --safe-b: env(safe-area-inset-bottom, 0px);
  --safe-l: env(safe-area-inset-left, 0px);
  --safe-r: env(safe-area-inset-right, 0px);
}

* { box-sizing: border-box; }

html {
  height: 100%;
  background: var(--bg);
  -webkit-text-size-adjust: 100%;
}

body {
  margin: 0;
  min-height: 100%;
  min-height: 100dvh;
  color: var(--text);
  font-family: var(--mono);
  font-size: 13px;
  line-height: 1.45;
  background:
    radial-gradient(circle at 12% 0%, rgba(255, 83, 73, 0.08), transparent 32rem),
    radial-gradient(circle at 88% 8%, rgba(71, 229, 255, 0.07), transparent 28rem),
    var(--bg);
  overscroll-behavior: none;
  -webkit-font-smoothing: antialiased;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 99;
  background: repeating-linear-gradient(to bottom, rgba(255, 255, 255, 0.018) 0, rgba(255, 255, 255, 0.018) 1px, transparent 1px, transparent 4px);
  mix-blend-mode: screen;
  opacity: 0.5;
}

button {
  color: inherit;
  font-family: inherit;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}

button, a { -webkit-user-select: none; user-select: none; }
::selection { background: var(--lime); color: #111; }

h1, h2, h3, h4, p { margin: 0; }
button { border: 0; background: none; cursor: pointer; }

.mono { font-family: var(--mono); }
.pixel { font-family: var(--display); }
.muted { color: var(--muted); }
.lime { color: var(--lime); }
.red { color: var(--red); }
.cyan { color: var(--cyan); }
.yellow { color: var(--yellow); }
.hidden { display: none !important; }

/* ---------- app chrome ---------- */
.app-shell {
  width: 100%;
  max-width: 1320px;
  min-height: 100dvh;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  position: relative;
}

.topbar {
  min-height: 64px;
  padding: 10px max(16px, var(--safe-l)) 10px max(16px, var(--safe-r));
  display: flex;
  align-items: center;
  gap: 16px;
  border-bottom: 1px solid var(--line-soft);
  background: rgba(8, 9, 17, 0.85);
  backdrop-filter: blur(12px);
  position: sticky;
  top: 0;
  z-index: 30;
}

.brand {
  display: flex;
  align-items: center;
  gap: 10px;
  cursor: pointer;
  min-width: 0;
}

.brand-helmet { width: 32px; height: 32px; flex: 0 0 auto; filter: drop-shadow(3px 3px 0 #000); }

.brand-copy { min-width: 0; }
.brand-name {
  display: block;
  font-family: var(--display);
  font-size: 9px;
  line-height: 1.2;
  letter-spacing: -0.5px;
  color: var(--text);
  white-space: nowrap;
}
.brand-sub {
  display: block;
  margin-top: 3px;
  font-size: 8px;
  letter-spacing: 2px;
  color: var(--muted);
  white-space: nowrap;
}

.topbar-spacer { flex: 1; }
.top-stats { display: flex; align-items: center; gap: 8px; }
.stat-chip {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-height: 36px;
  padding: 6px 10px;
  border: 1px solid var(--line);
  background: var(--panel);
  box-shadow: 3px 3px 0 #000;
}
.stat-chip .k { font-size: 7px; letter-spacing: 1.4px; color: var(--muted); }
.stat-chip .v { font-family: var(--display); font-size: 9px; color: var(--lime); line-height: 1.1; }
.stat-chip.plain .v { color: var(--text); }

.icon-btn {
  width: 38px;
  height: 38px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--line);
  background: var(--panel);
  color: var(--text);
  box-shadow: 3px 3px 0 #000;
  transition: transform 0.08s, box-shadow 0.08s, border-color 0.12s;
}
.icon-btn:hover { border-color: var(--lime); }
.icon-btn:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 #000; }
.icon-btn svg { width: 18px; height: 18px; }

.screen {
  flex: 1;
  width: 100%;
  min-height: 0;
  position: relative;
}
.screen.scroll { overflow-y: auto; overflow-x: hidden; -webkit-overflow-scrolling: touch; }

.bottomnav {
  position: sticky;
  bottom: 0;
  z-index: 30;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 3px;
  padding: 7px max(8px, var(--safe-l)) calc(7px + var(--safe-b)) max(8px, var(--safe-r));
  border-top: 1px solid var(--line-soft);
  background: rgba(9, 10, 18, 0.94);
  backdrop-filter: blur(14px);
}

.navbtn {
  min-height: 51px;
  padding: 4px 2px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
  color: var(--muted);
  border: 1px solid transparent;
  transition: color 0.12s, background 0.12s;
}
.navbtn svg { width: 20px; height: 20px; }
.navbtn span { font-size: 7px; letter-spacing: 1.2px; }
.navbtn.active { color: #111; background: var(--lime); box-shadow: 2px 2px 0 #000; }
.navbtn:hover:not(.active) { color: var(--text); background: rgba(255,255,255,0.04); }

/* ---------- common ---------- */
.page {
  width: 100%;
  max-width: 1180px;
  margin: 0 auto;
  padding: 20px clamp(14px, 3vw, 28px) 30px;
}
.page-head {
  display: flex;
  align-items: flex-end;
  gap: 14px;
  margin-bottom: 18px;
  flex-wrap: wrap;
}
.page-head .spacer { flex: 1; }
.kicker {
  font-size: 8px;
  letter-spacing: 2.2px;
  color: var(--lime);
  margin-bottom: 7px;
}
.page-title {
  font-family: var(--display);
  font-size: clamp(16px, 3vw, 26px);
  line-height: 1.38;
  letter-spacing: -1px;
}
.page-sub { color: var(--muted); font-size: 11px; margin-top: 5px; }

.panel {
  background: linear-gradient(145deg, var(--panel2), var(--panel));
  border: 1px solid var(--line);
  box-shadow: var(--shadow);
  position: relative;
}
.panel.pad { padding: 16px; }
.panel-title {
  font-family: var(--display);
  font-size: 8px;
  letter-spacing: 1px;
  line-height: 1.5;
  color: var(--muted);
  display: flex;
  align-items: center;
  gap: 8px;
}
.panel-title .dot { width: 6px; height: 6px; background: var(--lime); box-shadow: 0 0 8px var(--lime); flex: 0 0 auto; }

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-height: 44px;
  padding: 11px 18px;
  border: 2px solid var(--line);
  background: var(--panel2);
  color: var(--text);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  box-shadow: 4px 4px 0 #000;
  transition: transform 0.08s, box-shadow 0.08s, border-color 0.12s;
}
.btn:hover { border-color: var(--lime); }
.btn:active { transform: translate(3px, 3px); box-shadow: 1px 1px 0 #000; }
.btn.primary { background: var(--lime); border-color: var(--lime); color: #111; }
.btn.primary:hover { background: #e6ff78; }
.btn.red { background: var(--red); border-color: var(--red); color: #111; }
.btn.wide { width: 100%; }
.btn.big { min-height: 54px; padding: 16px 24px; font-size: 12px; }
.btn.ghost { background: transparent; box-shadow: none; }
.btn:disabled { opacity: 0.4; cursor: not-allowed; transform: none; box-shadow: 3px 3px 0 #000; }
.btn svg { width: 17px; height: 17px; }
.btn .arr { font-size: 14px; }

.tag {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  min-height: 22px;
  padding: 4px 7px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,0.035);
  color: var(--muted);
  font-size: 7px;
  letter-spacing: 1.2px;
  text-transform: uppercase;
  white-space: nowrap;
}
.tag.hot { border-color: rgba(255,83,73,.45); color: var(--red); background: rgba(255,83,73,.07); }
.tag.lime { border-color: rgba(216,255,62,.4); color: var(--lime); background: rgba(216,255,62,.05); }

.divider { height: 1px; background: var(--line-soft); margin: 14px 0; }
.row { display: flex; align-items: center; gap: 10px; }
.row.wrap { flex-wrap: wrap; }
.spacer { flex: 1; }

/* pixel meter */
.meter { height: 7px; background: #090a12; border: 1px solid #2a2d40; overflow: hidden; position: relative; }
.meter > i { display: block; height: 100%; background: var(--lime); box-shadow: 0 0 10px rgba(216,255,62,.4); transition: width .25s; }
.meter.red > i { background: var(--red); box-shadow: 0 0 10px rgba(255,83,73,.4); }
.meter.cyan > i { background: var(--cyan); }
.meter.small { height: 5px; }

/* ---------- title ---------- */
.title-screen {
  position: relative;
  min-height: 100dvh;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  background: #070810;
}
#titleCanvas {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  image-rendering: pixelated;
}
.title-shade {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(90deg, rgba(7,8,16,.92) 0%, rgba(7,8,16,.62) 38%, rgba(7,8,16,.12) 70%),
    linear-gradient(0deg, rgba(7,8,16,.98) 0%, rgba(7,8,16,.12) 55%, rgba(7,8,16,.4) 100%);
  pointer-events: none;
}
.title-top {
  position: relative;
  z-index: 2;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: max(18px, calc(8px + env(safe-area-inset-top))) clamp(18px, 4vw, 44px);
  gap: 12px;
}
.title-badge {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 7px 9px;
  background: rgba(7,8,16,.66);
  border: 1px solid rgba(255,255,255,.14);
  font-size: 7px;
  letter-spacing: 1.5px;
  color: #c8cad8;
  backdrop-filter: blur(4px);
}
.title-badge b { color: var(--lime); font-weight: 400; }
.title-content {
  position: relative;
  z-index: 2;
  margin-top: auto;
  padding: 4vh clamp(18px, 5vw, 68px) max(22px, calc(12px + env(safe-area-inset-bottom)));
  width: min(720px, 100%);
}
.title-eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--cyan);
  font-family: var(--display);
  font-size: clamp(7px, 1.2vw, 9px);
  letter-spacing: 1.4px;
  margin-bottom: 15px;
  text-shadow: 2px 2px 0 #000;
}
.title-eyebrow::before { content: ""; width: 34px; height: 3px; background: var(--cyan); box-shadow: 0 0 10px var(--cyan); }
.title-main {
  display: block;
  font-family: var(--display);
  font-size: clamp(36px, 9.2vw, 86px);
  line-height: 0.95;
  letter-spacing: -4px;
  color: var(--text);
  text-shadow: 6px 6px 0 #b1141c, 10px 10px 0 rgba(0,0,0,.45);
}
.title-main em { font-style: normal; color: var(--lime); text-shadow: 6px 6px 0 #445d09, 10px 10px 0 rgba(0,0,0,.45); }
.title-sub {
  display: inline-block;
  margin-top: 16px;
  padding: 8px 12px;
  background: var(--lime);
  color: #111;
  font-family: var(--display);
  font-size: clamp(10px, 2.2vw, 18px);
  line-height: 1.4;
  letter-spacing: -1px;
  box-shadow: 5px 5px 0 #000;
  transform: rotate(-1deg);
}
.title-copy {
  max-width: 510px;
  color: #c2c5d3;
  margin: 22px 0 20px;
  font-size: clamp(11px, 1.5vw, 14px);
  line-height: 1.7;
}
.title-actions { display: flex; flex-wrap: wrap; gap: 12px; align-items: stretch; }
.title-actions .btn { min-width: 170px; }
.save-jump {
  margin-top: 16px;
  border-left: 3px solid var(--lime);
  padding: 7px 0 7px 11px;
  color: var(--muted);
  font-size: 10px;
  line-height: 1.7;
}
.save-jump b { color: var(--text); font-weight: 400; }
.title-bottom {
  position: relative;
  z-index: 2;
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  padding: 14px clamp(18px, 5vw, 68px) max(18px, calc(10px + env(safe-area-inset-bottom)));
  color: #6f7489;
  font-size: 8px;
  letter-spacing: .8px;
  border-top: 1px solid rgba(255,255,255,.07);
}
.title-bottom .spacer { flex: 1; }

/* ---------- team select ---------- */
.select-screen {
  min-height: 100dvh;
  background:
    radial-gradient(circle at 15% 4%, rgba(255,83,73,.13), transparent 30rem),
    radial-gradient(circle at 88% 12%, rgba(71,229,255,.09), transparent 26rem),
    var(--bg);
}
.select-head {
  padding: max(18px, calc(8px + env(safe-area-inset-top))) clamp(16px, 3vw, 30px) 0;
  max-width: 1240px;
  margin: 0 auto;
}
.select-nav { display: flex; align-items: center; gap: 10px; margin-bottom: clamp(26px, 6vh, 54px); }
.select-title-wrap { max-width: 780px; margin-bottom: 22px; }
.select-title {
  font-family: var(--display);
  font-size: clamp(18px, 4vw, 34px);
  line-height: 1.45;
  letter-spacing: -1px;
  margin: 6px 0 10px;
}
.select-title span { color: var(--lime); }
.select-lead { color: var(--muted); font-size: 12px; max-width: 620px; line-height: 1.7; }
.team-grid {
  max-width: 1240px;
  margin: 0 auto;
  padding: 4px clamp(16px, 3vw, 30px) max(28px, calc(16px + var(--safe-b)));
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 14px;
}
.team-card {
  background: var(--panel);
  border: 1px solid var(--line);
  box-shadow: 4px 4px 0 #000;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  transition: transform .12s, border-color .12s;
  position: relative;
}
.team-card::before {
  content: "";
  position: absolute;
  top: 0; left: 0; right: 0; height: 4px;
  background: linear-gradient(90deg, var(--tc), var(--ta));
}
.team-card:hover { transform: translateY(-2px); border-color: #4b506b; }
.team-head { padding: 16px 14px 11px; border-bottom: 1px solid var(--line-soft); }
.team-logo-row { display: flex; align-items: flex-start; gap: 9px; }
.team-swatch {
  width: 11px;
  height: 38px;
  background: linear-gradient(180deg, var(--tc), var(--ta));
  box-shadow: 2px 2px 0 #000;
  flex: 0 0 auto;
}
.team-name { font-family: var(--display); font-size: 9px; line-height: 1.7; color: var(--text); }
.team-bike { margin-top: 4px; color: var(--muted); font-size: 8px; letter-spacing: .8px; }
.team-meta { display: flex; gap: 6px; flex-wrap: wrap; margin-top: 10px; }
.team-rating { margin-left: auto; text-align: right; }
.team-rating b { font-family: var(--display); font-size: 13px; color: var(--lime); display: block; line-height: 1; }
.team-rating span { font-size: 6px; letter-spacing: 1px; color: var(--muted); }
.rider-pick {
  display: flex;
  align-items: center;
  gap: 10px;
  width: 100%;
  padding: 10px 12px;
  border-top: 1px solid var(--line-soft);
  text-align: left;
  transition: background .12s;
}
.rider-pick:hover { background: rgba(255,255,255,.045); }
.rider-pick + .rider-pick { margin-top: 0; }
.rider-helmet {
  width: 35px;
  height: 35px;
  flex: 0 0 auto;
  display: grid;
  place-items: center;
  background: color-mix(in srgb, var(--tc) 25%, #0b0c15);
  border: 1px solid color-mix(in srgb, var(--tc) 60%, #2d3147);
  position: relative;
}
.rider-helmet svg { width: 23px; height: 23px; }
.rider-num {
  position: absolute;
  right: 2px;
  bottom: 1px;
  color: #fff;
  font-family: var(--display);
  font-size: 5px;
  background: rgba(0,0,0,.7);
  padding: 1px 2px;
}
.rider-info { min-width: 0; flex: 1; }
.rider-name { display: block; font-size: 10px; font-weight: 700; letter-spacing: .1px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.rider-meta { display: block; margin-top: 3px; font-size: 7px; color: var(--muted); letter-spacing: .7px; }
.rider-ovr { font-family: var(--display); font-size: 9px; color: var(--lime); white-space: nowrap; }
.rider-arrow { color: var(--muted); font-size: 15px; margin-left: 1px; }
.rider-pick:hover .rider-arrow { color: var(--lime); }

/* ---------- hub ---------- */
.hub-topline {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
  margin-bottom: 14px;
}
.team-strip {
  display: flex;
  align-items: center;
  gap: 9px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,.025);
  padding: 6px 9px;
  font-size: 8px;
  letter-spacing: 1px;
}
.team-strip .sq { width: 8px; height: 18px; background: var(--tc); }

.hub-grid {
  display: grid;
  grid-template-columns: repeat(12, minmax(0, 1fr));
  gap: 14px;
}
.span-4 { grid-column: span 4; }
.span-5 { grid-column: span 5; }
.span-6 { grid-column: span 6; }
.span-7 { grid-column: span 7; }
.span-8 { grid-column: span 8; }
.span-12 { grid-column: span 12; }

.race-hero {
  padding: clamp(16px, 2.5vw, 25px);
  display: grid;
  grid-template-columns: minmax(0, 1.25fr) minmax(150px, .75fr);
  gap: 10px;
  overflow: hidden;
  background:
    linear-gradient(120deg, color-mix(in srgb, var(--tc) 18%, #151725) 0%, #111321 55%, #10111d 100%);
}
.race-hero::after {
  content: "";
  position: absolute;
  right: -30px;
  top: -40px;
  width: 230px;
  height: 230px;
  border: 38px solid color-mix(in srgb, var(--tc) 17%, transparent);
  transform: rotate(22deg);
  pointer-events: none;
}
.race-hero-copy { position: relative; z-index: 1; }
.round-kicker { display: flex; align-items: center; gap: 8px; font-size: 8px; letter-spacing: 1.7px; color: var(--lime); }
.round-kicker b { color: var(--text); font-weight: 400; }
.race-name {
  font-family: var(--display);
  font-size: clamp(15px, 2.7vw, 25px);
  line-height: 1.55;
  margin: 10px 0 5px;
  letter-spacing: -1px;
}
.circuit-name { color: var(--muted); font-size: 10px; letter-spacing: .5px; }
.race-facts { display: flex; flex-wrap: wrap; gap: 7px; margin: 15px 0 17px; }
.race-fact {
  border: 1px solid rgba(255,255,255,.11);
  background: rgba(0,0,0,.18);
  padding: 6px 8px;
  font-size: 8px;
  color: #bfc2d1;
}
.race-fact b { color: var(--text); font-weight: 400; }
.race-hero-actions { display: flex; flex-wrap: wrap; gap: 8px; position: relative; z-index: 1; }
.race-map-mini {
  align-self: center;
  justify-self: center;
  width: 100%;
  max-width: 205px;
  aspect-ratio: 1;
  position: relative;
  z-index: 1;
  filter: drop-shadow(5px 6px 0 rgba(0,0,0,.35));
}
.race-map-mini svg { width: 100%; height: 100%; display: block; }
.map-caption {
  position: absolute;
  bottom: -3px;
  left: 50%;
  transform: translateX(-50%);
  white-space: nowrap;
  font-size: 6px;
  letter-spacing: 1.2px;
  color: var(--muted);
}

.paddock-card { padding: 16px; }
.rider-hero { display: flex; gap: 12px; align-items: center; margin: 14px 0; }
.rider-big-helmet {
  width: 62px;
  height: 62px;
  background: color-mix(in srgb, var(--tc) 21%, #0b0c15);
  border: 2px solid color-mix(in srgb, var(--tc) 74%, #2d3147);
  display: grid;
  place-items: center;
  box-shadow: 4px 4px 0 #000;
  flex: 0 0 auto;
}
.rider-big-helmet svg { width: 43px; height: 43px; }
.rider-big-name { font-family: var(--display); font-size: 10px; line-height: 1.7; }
.rider-big-team { color: var(--muted); font-size: 8px; margin-top: 5px; letter-spacing: .8px; }
.ovr-badge {
  margin-left: auto;
  text-align: right;
}
.ovr-badge b { display: block; font-family: var(--display); font-size: 22px; color: var(--lime); line-height: 1; }
.ovr-badge span { font-size: 6px; color: var(--muted); letter-spacing: 1px; }
.attr-list { display: grid; gap: 9px; }
.attr-row { display: grid; grid-template-columns: 62px 1fr 22px; align-items: center; gap: 8px; font-size: 7px; color: var(--muted); letter-spacing: .7px; }
.attr-row b { color: var(--text); font-weight: 400; text-align: right; font-size: 8px; }

.panel-head { display: flex; align-items: center; gap: 8px; margin-bottom: 13px; }
.panel-head .spacer { flex: 1; }

.mini-table { display: grid; gap: 1px; }
.mini-row {
  display: grid;
  grid-template-columns: 24px 1fr 36px;
  align-items: center;
  gap: 8px;
  padding: 7px 6px;
  background: rgba(255,255,255,.018);
  font-size: 9px;
}
.mini-row:nth-child(even) { background: rgba(255,255,255,.035); }
.mini-row.you { background: rgba(216,255,62,.09); box-shadow: inset 2px 0 var(--lime); }
.mini-pos { font-family: var(--display); font-size: 7px; color: var(--muted); }
.mini-name { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.mini-name i { display: inline-block; width: 5px; height: 10px; background: var(--tc); margin-right: 5px; vertical-align: -1px; }
.mini-pts { text-align: right; font-family: var(--display); font-size: 7px; color: var(--lime); }

.news-feed { display: grid; gap: 9px; }
.news-item { display: flex; gap: 9px; font-size: 9px; line-height: 1.6; color: #b9bcca; }
.news-item::before { content: ">"; color: var(--lime); flex: 0 0 auto; }
.news-item small { display: block; color: #666c84; font-size: 7px; margin-top: 2px; letter-spacing: 1px; }

.calendar-strip { display: flex; gap: 6px; overflow-x: auto; padding: 2px 1px 7px; scrollbar-width: thin; }
.cal-chip {
  min-width: 58px;
  padding: 7px 6px;
  border: 1px solid var(--line);
  background: #0e101b;
  text-align: left;
  flex: 0 0 auto;
  position: relative;
}
.cal-chip.done { opacity: .52; }
.cal-chip.next { border-color: var(--lime); box-shadow: inset 0 -2px var(--lime); }
.cal-chip .r { font-family: var(--display); font-size: 6px; color: var(--muted); }
.cal-chip .c { margin-top: 4px; font-size: 7px; letter-spacing: .5px; white-space: nowrap; color: var(--text); }
.cal-chip .w { margin-top: 3px; font-size: 6px; color: var(--muted); }
.cal-chip.next .c { color: var(--lime); }

.money-strip { display: grid; grid-template-columns: repeat(3, 1fr); gap: 8px; margin-top: 12px; }
.money-cell { border: 1px solid var(--line-soft); background: rgba(0,0,0,.17); padding: 8px; }
.money-cell .k { font-size: 6px; letter-spacing: 1px; color: var(--muted); display: block; }
.money-cell .v { font-family: var(--display); font-size: 9px; margin-top: 4px; color: var(--text); display: block; }
.money-cell .v.lime { color: var(--lime); }

/* ---------- weekend / briefing ---------- */
.weekend-shell {
  min-height: 100dvh;
  background:
    radial-gradient(circle at 50% -20%, color-mix(in srgb, var(--tc, #ff5349) 14%, transparent), transparent 38rem),
    var(--bg);
  display: flex;
  flex-direction: column;
}
.weekend-head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: max(12px, calc(6px + env(safe-area-inset-top))) clamp(12px, 3vw, 28px);
  border-bottom: 1px solid var(--line-soft);
  background: rgba(8,9,17,.8);
  backdrop-filter: blur(10px);
  position: sticky;
  top: 0;
  z-index: 20;
}
.weekend-progress { display: flex; align-items: center; gap: 4px; margin-left: auto; }
.wp-step {
  padding: 4px 7px;
  border: 1px solid var(--line);
  color: #6e748c;
  font-size: 6px;
  letter-spacing: 1px;
}
.wp-step.active { border-color: var(--lime); color: var(--lime); background: rgba(216,255,62,.06); }
.wp-step.done { color: #b9bcc9; }
.wp-step + .wp-step::before { content: ">"; margin-right: 7px; color: #4a4e62; }
.weekend-body {
  width: 100%;
  max-width: 980px;
  margin: 0 auto;
  padding: 20px clamp(13px, 3vw, 26px) 32px;
  flex: 1;
}
.weekend-title {
  font-family: var(--display);
  font-size: clamp(14px, 3vw, 22px);
  line-height: 1.55;
  letter-spacing: -1px;
  margin: 5px 0;
}
.weekend-sub { color: var(--muted); font-size: 10px; }
.weather-panel { display: flex; flex-wrap: wrap; gap: 14px; align-items: center; padding: 13px 15px; margin: 16px 0; }
.weather-icon { font-family: var(--display); font-size: 18px; color: var(--yellow); line-height: 1; }
.weather-main b { display: block; font-family: var(--display); font-size: 8px; line-height: 1.4; }
.weather-main span { display: block; font-size: 8px; color: var(--muted); margin-top: 4px; }
.weather-note { margin-left: auto; max-width: 340px; font-size: 8px; color: var(--muted); line-height: 1.6; }

.option-section { margin-top: 20px; }
.section-label {
  display: flex;
  align-items: center;
  gap: 7px;
  margin-bottom: 9px;
  color: var(--muted);
  font-family: var(--display);
  font-size: 7px;
  letter-spacing: .8px;
}
.section-label .num { color: var(--lime); }
.tyre-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
.tyre-card, .setup-card {
  text-align: left;
  padding: 12px 10px;
  border: 1px solid var(--line);
  background: var(--panel);
  box-shadow: 3px 3px 0 rgba(0,0,0,.5);
  transition: border-color .12s, background .12s, transform .08s;
  min-height: 96px;
}
.tyre-card:hover, .setup-card:hover { border-color: #555b78; }
.tyre-card.selected, .setup-card.selected { border-color: var(--lime); background: rgba(216,255,62,.065); box-shadow: 3px 3px 0 #000, inset 0 -3px var(--lime); }
.tyre-dot { width: 16px; height: 16px; border: 2px solid #090a12; box-shadow: 0 0 0 1px rgba(255,255,255,.18); margin-bottom: 10px; }
.tyre-card .tname { font-family: var(--display); font-size: 8px; line-height: 1.5; }
.tyre-card .tdesc { margin-top: 6px; color: var(--muted); font-size: 7px; line-height: 1.5; min-height: 21px; }
.tyre-stats { display: flex; gap: 8px; margin-top: 8px; font-size: 6px; color: var(--muted); }
.tyre-stats b { color: var(--text); font-weight: 400; }
.setup-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 8px; }
.setup-card { min-height: 82px; display: flex; flex-direction: column; justify-content: space-between; }
.setup-glyph { font-family: var(--display); font-size: 13px; color: var(--lime); }
.setup-card .sname { font-family: var(--display); font-size: 7px; line-height: 1.5; margin-top: 7px; }
.setup-card .snote { color: var(--muted); font-size: 7px; line-height: 1.5; margin-top: 5px; }

.brief-summary {
  margin-top: 20px;
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 12px;
  align-items: center;
  padding: 14px;
}
.summary-line { display: flex; gap: 7px; flex-wrap: wrap; }
.summary-line .tag { min-height: 25px; }
.weekend-foot {
  padding: 14px clamp(13px, 3vw, 26px) calc(16px + var(--safe-b));
  background: rgba(9,10,18,.92);
  border-top: 1px solid var(--line);
  position: sticky;
  bottom: 0;
  z-index: 20;
}
.weekend-foot .inner { max-width: 980px; margin: 0 auto; display: flex; align-items: center; gap: 12px; }
.weekend-foot .hint { color: var(--muted); font-size: 8px; line-height: 1.5; }

/* ---------- qualifying ---------- */
.quali-shell { min-height: 100dvh; display: flex; flex-direction: column; }
.quali-body { width: min(900px, 100%); margin: 0 auto; padding: 20px clamp(14px, 3vw, 28px) 30px; flex: 1; display: flex; flex-direction: column; }
.quali-header { display: flex; align-items: flex-start; gap: 14px; flex-wrap: wrap; }
.quali-grid-mini { display: flex; gap: 6px; flex-wrap: wrap; margin-left: auto; }
.quali-stage {
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  max-width: 760px;
  margin: 12px auto 0;
  width: 100%;
}
.quali-lights { display: flex; align-items: center; gap: 8px; justify-content: center; margin-bottom: 18px; color: var(--muted); font-size: 7px; letter-spacing: 1.4px; }
.q-leds { display: flex; gap: 5px; }
.q-led { width: 8px; height: 8px; background: #242737; border: 1px solid #383c52; }
.q-led.on { background: var(--red); border-color: var(--red); box-shadow: 0 0 9px var(--red); }
.q-led.green { background: var(--lime); border-color: var(--lime); box-shadow: 0 0 10px var(--lime); }

.quali-gauge-card { padding: clamp(16px, 3vw, 25px); }
.gauge-readout { display: flex; align-items: baseline; gap: 12px; margin-bottom: 16px; flex-wrap: wrap; }
.gauge-readout .sector-word { font-family: var(--display); font-size: 9px; color: var(--lime); }
.gauge-readout .delta { margin-left: auto; font-family: var(--display); font-size: 15px; color: var(--text); }
.gauge-track {
  height: 58px;
  border: 2px solid #383c54;
  background:
    linear-gradient(90deg, #3a1320 0%, #5a1d22 14%, #4b3422 26%, #27392a 38%, #20422e 47%, #245035 50%, #20422e 53%, #27392a 62%, #4b3422 74%, #5a1d22 86%, #3a1320 100%);
  position: relative;
  overflow: hidden;
  box-shadow: inset 0 0 20px #000;
  cursor: pointer;
}
.gauge-track::after {
  content: "";
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(90deg, transparent 0, transparent 9px, rgba(0,0,0,.24) 9px, rgba(0,0,0,.24) 10px);
  pointer-events: none;
}
.gauge-zone {
  position: absolute;
  top: 0; bottom: 0;
  left: 38%; width: 24%;
  background: rgba(216,255,62,.16);
  border-left: 2px solid rgba(216,255,62,.7);
  border-right: 2px solid rgba(216,255,62,.7);
}
.gauge-zone::before {
  content: "";
  position: absolute;
  top: 0; bottom: 0;
  left: 50%; width: 6%;
  transform: translateX(-50%);
  background: rgba(216,255,62,.29);
  border-left: 1px solid rgba(216,255,62,.7);
  border-right: 1px solid rgba(216,255,62,.7);
}
.gauge-cursor {
  position: absolute;
  top: -3px; bottom: -3px;
  left: 50%;
  width: 7px;
  background: #fff;
  box-shadow: 0 0 14px #fff, 4px 0 0 rgba(0,0,0,.45);
  transform: translateX(-50%);
  z-index: 2;
}
.gauge-labels { display: flex; justify-content: space-between; margin-top: 8px; font-size: 6px; letter-spacing: 1px; color: var(--muted); }
.sector-row { display: grid; grid-template-columns: repeat(3, 1fr); gap: 7px; margin-top: 16px; }
.sector-cell { border: 1px solid var(--line); padding: 9px; background: rgba(0,0,0,.18); }
.sector-cell .sk { font-size: 6px; letter-spacing: 1px; color: var(--muted); }
.sector-cell .sv { display: block; font-family: var(--display); font-size: 10px; margin-top: 6px; color: #555b74; }
.sector-cell.good .sv { color: var(--lime); }
.sector-cell.bad .sv { color: var(--red); }
.sector-cell.live { border-color: var(--cyan); }
.q-push-wrap { display: flex; flex-direction: column; align-items: center; gap: 7px; margin-top: 18px; }
.q-push {
  width: 100%;
  max-width: 410px;
  min-height: 72px;
  background: var(--lime);
  color: #111;
  border: 3px solid var(--lime);
  font-family: var(--display);
  font-size: 15px;
  box-shadow: 6px 6px 0 #000;
  transition: transform .06s, box-shadow .06s, background .1s;
  touch-action: manipulation;
}
.q-push:active { transform: translate(4px,4px); box-shadow: 2px 2px 0 #000; }
.q-push:disabled { opacity: .35; }
.q-push-wrap .q-hint { color: var(--muted); font-size: 8px; letter-spacing: .7px; text-align: center; }
.quali-progress-note { margin-top: 15px; display: flex; justify-content: center; gap: 12px; font-size: 7px; color: var(--muted); }
.quali-progress-note b { color: var(--text); font-weight: 400; }

/* quali result overlay / grid */
.grid-overlay {
  background: rgba(4,5,9,.9);
  border: 1px solid var(--line);
  box-shadow: 8px 8px 0 #000;
  width: min(760px, 100%);
  margin: auto;
  max-height: calc(100dvh - 34px);
  display: flex;
  flex-direction: column;
}
.grid-overlay-head { padding: 15px 18px; border-bottom: 1px solid var(--line); display: flex; align-items: center; gap: 10px; }
.grid-overlay-head h3 { font-family: var(--display); font-size: 10px; line-height: 1.5; }
.grid-overlay-head .tag { margin-left: auto; }
.grid-table-wrap { overflow-y: auto; padding: 5px 0; }
.grid-table { width: 100%; border-collapse: collapse; font-size: 9px; }
.grid-table th { position: sticky; top: 0; background: #11131f; color: var(--muted); font-size: 6px; letter-spacing: 1px; text-align: left; padding: 7px 9px; z-index: 1; }
.grid-table td { padding: 5px 9px; border-top: 1px solid rgba(255,255,255,.035); }
.grid-table tr.you td { background: rgba(216,255,62,.09); color: var(--lime); }
.grid-table .pos { font-family: var(--display); font-size: 7px; width: 38px; color: var(--muted); }
.grid-table tr.you .pos { color: var(--lime); }
.grid-table .rnum { width: 32px; color: var(--muted); }
.grid-table .dot { width: 5px; height: 5px; display: inline-block; background: var(--tc); margin-right: 6px; }
.grid-overlay-foot { padding: 13px 18px calc(13px + var(--safe-b)); border-top: 1px solid var(--line); display: flex; gap: 10px; align-items: center; }
.grid-overlay-foot .spacer { flex: 1; }

/* ---------- race ---------- */
.race-shell {
  height: 100dvh;
  min-height: 520px;
  background: #06070c;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  --tc: #ff5349;
}
.race-top {
  flex: 0 0 auto;
  height: 52px;
  padding: 0 max(10px, var(--safe-l)) 0 max(10px, var(--safe-r));
  display: flex;
  align-items: center;
  gap: 9px;
  border-bottom: 1px solid #232637;
  background: rgba(9,10,17,.95);
  position: relative;
  z-index: 15;
}
.race-top .icon-btn { width: 34px; height: 34px; background: #10121d; }
.race-heading { min-width: 0; flex: 1; }
.race-heading .k { font-size: 6px; letter-spacing: 1.4px; color: var(--muted); }
.race-heading .n { font-family: var(--display); font-size: 7px; line-height: 1.5; color: var(--text); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; margin-top: 3px; }
.race-weather { display: flex; align-items: center; gap: 6px; font-size: 7px; color: var(--muted); }
.race-weather b { color: var(--text); font-weight: 400; }
.speed-toggle {
  min-width: 40px;
  height: 32px;
  border: 1px solid #373c54;
  background: #121524;
  color: var(--lime);
  font-family: var(--display);
  font-size: 8px;
}
.race-track-wrap {
  flex: 1 1 auto;
  min-height: 0;
  position: relative;
  overflow: hidden;
  background: #0a0d10;
}
#raceCanvas { position: absolute; inset: 0; width: 100%; height: 100%; image-rendering: pixelated; }
.race-vignette { position: absolute; inset: 0; pointer-events: none; background: radial-gradient(ellipse at center, transparent 40%, rgba(0,0,0,.42) 100%); }
.race-hud {
  position: absolute;
  inset: 0;
  pointer-events: none;
  padding: 10px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.race-hud-top { display: flex; align-items: flex-start; gap: 7px; }
.pos-block {
  background: rgba(6,7,12,.78);
  border: 1px solid rgba(255,255,255,.13);
  padding: 6px 9px;
  backdrop-filter: blur(3px);
  min-width: 58px;
}
.pos-block .k { font-size: 6px; letter-spacing: 1.3px; color: var(--muted); }
.pos-block .v { font-family: var(--display); font-size: clamp(17px, 3vw, 24px); line-height: 1.25; color: var(--lime); }
.pos-block .v small { font-family: var(--mono); font-size: 7px; color: var(--muted); }
.lap-block {
  background: rgba(6,7,12,.78);
  border: 1px solid rgba(255,255,255,.13);
  padding: 7px 9px;
  backdrop-filter: blur(3px);
  min-width: 66px;
}
.lap-block .k { font-size: 6px; letter-spacing: 1.3px; color: var(--muted); }
.lap-block .v { font-family: var(--display); font-size: 8px; line-height: 1.5; margin-top: 3px; }
.gap-block { margin-left: auto; text-align: right; background: rgba(6,7,12,.78); border: 1px solid rgba(255,255,255,.13); padding: 7px 9px; backdrop-filter: blur(3px); }
.gap-block .k { font-size: 6px; letter-spacing: 1.2px; color: var(--muted); }
.gap-block .v { font-family: var(--display); font-size: 8px; margin-top: 3px; color: var(--cyan); }
.race-board {
  position: absolute;
  top: 76px;
  right: 10px;
  width: 146px;
  background: rgba(6,7,12,.72);
  border: 1px solid rgba(255,255,255,.11);
  backdrop-filter: blur(3px);
  pointer-events: none;
}
.race-board-title { padding: 5px 7px; font-size: 5px; letter-spacing: 1.2px; color: var(--muted); border-bottom: 1px solid rgba(255,255,255,.08); }
.race-board-row { display: grid; grid-template-columns: 18px 1fr 28px; gap: 4px; padding: 3px 6px; font-size: 7px; color: #c9cbd6; }
.race-board-row.you { color: var(--lime); background: rgba(216,255,62,.09); }
.race-board-row .p { font-family: var(--display); font-size: 5px; color: var(--muted); }
.race-board-row.you .p { color: var(--lime); }
.race-board-row .n { white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.race-board-row .g { text-align: right; font-size: 6px; color: var(--muted); }
.race-banner {
  position: absolute;
  left: 50%;
  top: 42%;
  transform: translate(-50%, -50%);
  font-family: var(--display);
  font-size: clamp(12px, 3.6vw, 24px);
  color: var(--lime);
  text-align: center;
  text-shadow: 4px 4px 0 #000;
  line-height: 1.5;
  padding: 8px 12px;
  background: rgba(6,7,12,.4);
  pointer-events: none;
  opacity: 0;
  transition: opacity .18s;
}
.race-banner.show { opacity: 1; }
.race-banner small { display: block; font-family: var(--mono); font-size: 8px; letter-spacing: 2px; color: var(--text); margin-top: 9px; }
.start-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 16px;
  background: rgba(5,6,11,.44);
  pointer-events: none;
  z-index: 4;
}
.start-lights { display: flex; gap: 10px; padding: 12px 14px; background: #0a0b12; border: 3px solid #2b2e42; box-shadow: 6px 6px 0 rgba(0,0,0,.6); }
.start-lamp { width: clamp(26px, 6vw, 44px); height: clamp(26px, 6vw, 44px); border-radius: 50%; background: #241b20; border: 3px solid #39303a; transition: background .15s, box-shadow .15s; }
.start-lamp.on { background: var(--red); border-color: #ff8b84; box-shadow: 0 0 20px var(--red); }
.start-lamp.go { background: var(--lime); border-color: #efffb2; box-shadow: 0 0 26px var(--lime); }
.start-caption { font-family: var(--display); font-size: 8px; color: #d5d7e3; letter-spacing: 1px; text-shadow: 3px 3px 0 #000; }
.race-radio {
  position: absolute;
  left: 50%;
  bottom: 13px;
  transform: translateX(-50%) translateY(20px);
  max-width: min(540px, 88%);
  padding: 7px 11px;
  background: rgba(7,8,14,.9);
  border-left: 3px solid var(--lime);
  font-size: 8px;
  line-height: 1.55;
  color: #d0d2dc;
  opacity: 0;
  transition: opacity .2s, transform .2s;
  pointer-events: none;
  text-align: center;
}
.race-radio.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.race-radio b { color: var(--lime); font-weight: 400; }
.pit-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  background: rgba(5,6,11,.55);
  z-index: 5;
  pointer-events: none;
  opacity: 0;
  transition: opacity .16s;
}
.pit-overlay.show { opacity: 1; }
.pit-card { text-align: center; padding: 18px 24px; background: #0a0b13; border: 2px solid var(--yellow); box-shadow: 6px 6px 0 #000; }
.pit-card .big { font-family: var(--display); font-size: 15px; color: var(--yellow); line-height: 1.4; }
.pit-card .sm { margin-top: 8px; font-size: 8px; color: var(--muted); letter-spacing: 1px; }
.race-console {
  flex: 0 0 auto;
  padding: 8px max(10px, var(--safe-l)) calc(8px + var(--safe-b)) max(10px, var(--safe-r));
  background: linear-gradient(180deg, #10121d, #090a11);
  border-top: 1px solid #2a2e42;
  display: grid;
  gap: 7px;
  position: relative;
  z-index: 10;
}
.race-metrics { display: flex; align-items: center; gap: 7px; }
.metric-box { flex: 1; min-width: 0; border: 1px solid #2a2e40; background: #0b0d16; padding: 5px 7px; }
.metric-box .k { display: flex; justify-content: space-between; font-size: 6px; letter-spacing: 1px; color: var(--muted); }
.metric-box .k b { color: var(--text); font-weight: 400; }
.metric-box .meter { margin-top: 5px; }
.metric-box.tyre { flex: 1.15; }
.pace-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 5px; }
.pace-btn {
  min-height: 41px;
  border: 1px solid #353a50;
  background: #121522;
  color: #a6aabd;
  font-family: var(--display);
  font-size: 7px;
  line-height: 1.4;
  padding: 5px 2px;
  box-shadow: 2px 2px 0 #000;
  position: relative;
}
.pace-btn .wear { display: block; font-family: var(--mono); font-size: 6px; color: #6e7488; margin-top: 4px; letter-spacing: .5px; }
.pace-btn.selected { border-color: var(--pc); color: #111; background: var(--pc); box-shadow: 2px 2px 0 #000, inset 0 -3px rgba(0,0,0,.2); }
.pace-btn.selected .wear { color: rgba(0,0,0,.6); }
.race-actions { display: grid; grid-template-columns: 1fr auto; gap: 7px; }
.box-btn {
  min-height: 42px;
  border: 1px solid rgba(255,210,63,.45);
  background: rgba(255,210,63,.08);
  color: var(--yellow);
  font-family: var(--display);
  font-size: 7px;
  line-height: 1.4;
  box-shadow: 2px 2px 0 #000;
}
.box-btn:disabled { opacity: .35; }
.race-actions .speed-toggle { height: 42px; width: 58px; }

/* ---------- results ---------- */
.results-shell { min-height: 100dvh; background: radial-gradient(circle at 50% -10%, color-mix(in srgb, var(--tc) 18%, transparent), transparent 34rem), var(--bg); }
.results-body { max-width: 990px; margin: 0 auto; padding: 20px clamp(13px, 3vw, 26px) 32px; }
.result-hero { display: grid; grid-template-columns: 1fr auto; gap: 16px; align-items: center; padding: 18px; margin-bottom: 13px; background: linear-gradient(120deg, color-mix(in srgb, var(--tc) 19%, #141623), #10111d); }
.result-pos { font-family: var(--display); font-size: clamp(24px, 6vw, 48px); color: var(--lime); line-height: 1; text-shadow: 4px 4px 0 #000; }
.result-pos small { font-family: var(--mono); font-size: 10px; color: var(--muted); letter-spacing: 1px; display: block; margin-top: 8px; }
.result-title { font-family: var(--display); font-size: clamp(10px, 2vw, 14px); line-height: 1.6; margin-top: 9px; }
.result-sub { margin-top: 4px; color: var(--muted); font-size: 9px; }
.result-reward { text-align: right; }
.result-reward .k { font-size: 7px; color: var(--muted); letter-spacing: 1px; }
.result-reward .v { font-family: var(--display); font-size: 19px; color: var(--lime); margin-top: 5px; line-height: 1; }
.result-reward .bonus { font-size: 7px; color: var(--yellow); margin-top: 6px; }
.results-grid { display: grid; grid-template-columns: 1.25fr .75fr; gap: 13px; }
.result-table { width: 100%; border-collapse: collapse; font-size: 9px; }
.result-table th { text-align: left; padding: 6px 8px; color: var(--muted); font-size: 6px; letter-spacing: 1px; background: rgba(0,0,0,.2); }
.result-table td { padding: 6px 8px; border-top: 1px solid rgba(255,255,255,.04); }
.result-table tr.you td { background: rgba(216,255,62,.09); color: var(--lime); }
.result-table .pos { font-family: var(--display); font-size: 7px; color: var(--muted); width: 36px; }
.result-table tr.you .pos { color: var(--lime); }
.result-table .dot { width: 5px; height: 5px; display: inline-block; background: var(--tc); margin-right: 5px; }
.result-table .pts { text-align: right; font-family: var(--display); font-size: 7px; }
.result-story { padding: 14px; }
.result-story p { color: #b9bcc9; font-size: 9px; line-height: 1.7; margin-bottom: 10px; }
.race-feed-list { display: grid; gap: 7px; margin-top: 10px; }
.feed-line { display: flex; gap: 7px; font-size: 8px; color: var(--muted); line-height: 1.5; }
.feed-line b { color: var(--text); font-weight: 400; }

/* ---------- standings ---------- */
.tabs { display: inline-flex; border: 1px solid var(--line); background: #0b0d16; }
.tab { min-height: 34px; padding: 7px 13px; font-size: 8px; letter-spacing: 1px; color: var(--muted); }
.tab.active { background: var(--lime); color: #111; }
.table-panel { padding: 0; overflow: hidden; }
.champ-table { width: 100%; border-collapse: collapse; font-size: 10px; }
.champ-table th { text-align: left; padding: 9px 11px; font-size: 6px; letter-spacing: 1.2px; color: var(--muted); background: #0d0f19; border-bottom: 1px solid var(--line); position: sticky; top: 0; z-index: 1; }
.champ-table td { padding: 8px 11px; border-bottom: 1px solid rgba(255,255,255,.035); }
.champ-table tbody tr:hover { background: rgba(255,255,255,.025); }
.champ-table tr.you td { background: rgba(216,255,62,.085); color: var(--lime); }
.champ-table .pos { width: 44px; font-family: var(--display); font-size: 7px; color: var(--muted); }
.champ-table tr.you .pos { color: var(--lime); }
.champ-table .team-cell { font-size: 8px; color: var(--muted); }
.champ-table tr.you .team-cell { color: #a6c94a; }
.champ-table .pts { text-align: right; font-family: var(--display); font-size: 8px; white-space: nowrap; }
.champ-table .bar { width: 100px; }
.pts-bar { height: 5px; background: #1d2030; position: relative; }
.pts-bar i { display: block; height: 100%; background: var(--lime); }
.champ-table tr.you .pts-bar i { background: var(--lime); box-shadow: 0 0 10px var(--lime); }
.legend-row { display: flex; gap: 14px; flex-wrap: wrap; color: var(--muted); font-size: 7px; margin-top: 10px; }
.legend-row b { color: var(--text); font-weight: 400; }
.calendar-grid { display: grid; grid-template-columns: repeat(7, 1fr); gap: 7px; }
.calendar-card { padding: 9px; border: 1px solid var(--line); background: #0e101b; min-height: 70px; }
.calendar-card.next { border-color: var(--lime); background: rgba(216,255,62,.05); }
.calendar-card.done { opacity: .5; }
.calendar-card .r { font-family: var(--display); font-size: 6px; color: var(--muted); }
.calendar-card .n { font-size: 8px; margin-top: 5px; line-height: 1.4; }
.calendar-card .s { font-size: 6px; color: var(--lime); margin-top: 5px; letter-spacing: .7px; }

/* ---------- garage ---------- */
.garage-grid { display: grid; grid-template-columns: 1fr 1.25fr; gap: 14px; align-items: start; }
.bike-card { padding: 16px; background: linear-gradient(145deg, color-mix(in srgb, var(--tc) 12%, #171a2a), #11131f); }
.bike-visual {
  height: 132px;
  margin: 12px 0 15px;
  border: 1px solid rgba(255,255,255,.08);
  background:
    linear-gradient(180deg, transparent 0 60%, rgba(0,0,0,.4)),
    repeating-linear-gradient(90deg, rgba(255,255,255,.025) 0 1px, transparent 1px 22px),
    #090b12;
  position: relative;
  overflow: hidden;
  display: grid;
  place-items: center;
}
.bike-visual::before {
  content: "";
  position: absolute;
  left: 8%; right: 8%; bottom: 20px;
  height: 2px;
  background: repeating-linear-gradient(90deg, #41465c 0 8px, transparent 8px 16px);
}
.bike-visual svg { width: 165px; height: 90px; filter: drop-shadow(5px 5px 0 rgba(0,0,0,.35)); }
.bike-model { font-family: var(--display); font-size: 9px; line-height: 1.6; }
.bike-team { color: var(--muted); font-size: 8px; margin-top: 4px; }
.bike-stats { display: grid; gap: 10px; margin-top: 14px; }
.bike-stat .lab { display: flex; justify-content: space-between; font-size: 7px; color: var(--muted); margin-bottom: 5px; letter-spacing: .8px; }
.bike-stat .lab b { color: var(--text); font-weight: 400; }
.upgrade-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 9px; }
.upgrade-card { padding: 12px; border: 1px solid var(--line); background: var(--panel); display: flex; flex-direction: column; }
.upgrade-top { display: flex; align-items: flex-start; gap: 8px; }
.upgrade-icon { width: 27px; height: 27px; display: grid; place-items: center; border: 1px solid var(--line); color: var(--lime); font-family: var(--display); font-size: 8px; background: #0b0d16; }
.upgrade-name { font-family: var(--display); font-size: 7px; line-height: 1.5; }
.upgrade-lvl { color: var(--muted); font-size: 6px; margin-top: 4px; letter-spacing: 1px; }
.pips { display: flex; gap: 3px; margin: 10px 0 7px; }
.pip { height: 6px; flex: 1; background: #252838; }
.pip.on { background: var(--lime); box-shadow: 0 0 5px rgba(216,255,62,.35); }
.upgrade-desc { color: var(--muted); font-size: 7px; line-height: 1.5; min-height: 32px; }
.upgrade-btn { margin-top: 9px; min-height: 30px; padding: 5px 8px; font-size: 7px; }
.upgrade-btn.maxed { opacity: .5; }
.career-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 7px; margin-top: 10px; }
.career-stat { padding: 9px; border: 1px solid var(--line-soft); background: #0d0f19; text-align: center; }
.career-stat b { display: block; font-family: var(--display); font-size: 12px; color: var(--lime); line-height: 1; }
.career-stat span { display: block; margin-top: 5px; font-size: 6px; color: var(--muted); letter-spacing: .8px; }
.settings-panel { margin-top: 14px; padding: 14px; display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
