.season-card { width: min(760px, 100%); padding: clamp(20px, 4vw, 38px); text-align: center; background: linear-gradient(180deg, #181523, #0f111b); border: 1px solid #3a3345; box-shadow: 10px 10px 0 #000; position: relative; overflow: hidden; }
.season-card::before { content: ""; position: absolute; inset: 0; background: repeating-linear-gradient(135deg, transparent 0 30px, rgba(255,210,63,.035) 30px 32px); pointer-events: none; }
.season-trophy { font-family: var(--display); font-size: clamp(40px, 9vw, 70px); color: var(--yellow); text-shadow: 5px 5px 0 #000; line-height: 1; margin-bottom: 20px; }
.season-title { font-family: var(--display); font-size: clamp(16px, 3.5vw, 26px); line-height: 1.5; }
.season-sub { color: var(--muted); font-size: 11px; margin: 10px auto 22px; max-width: 520px; line-height: 1.7; }
.season-table { width: 100%; border-collapse: collapse; font-size: 9px; margin: 16px 0 22px; text-align: left; }
.season-table td { padding: 7px 9px; border-bottom: 1px solid rgba(255,255,255,.05); }
