.season-table .pts { text-align: right; font-family: var(--display); font-size: 7px; }
.season-actions { display: flex; gap: 10px; justify-content: center; flex-wrap: wrap; }

/* ---------- modal / toast ---------- */
.modal-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  background: rgba(3,4,8,.82);
  backdrop-filter: blur(5px);
  opacity: 0;
  animation: fadeIn .15s forwards;
}
.modal {
  width: min(470px, 100%);
  background: linear-gradient(150deg, #191c2c, #10121e);
  border: 1px solid #3a3f58;
  box-shadow: 8px 8px 0 #000;
  padding: 18px;
  animation: popIn .18s cubic-bezier(.2,1.4,.4,1);
}
.modal-head { display: flex; gap: 10px; align-items: flex-start; margin-bottom: 14px; }
.modal-head h3 { font-family: var(--display); font-size: 10px; line-height: 1.6; }
.modal-head .close { margin-left: auto; }
.modal-team { display: flex; align-items: center; gap: 9px; padding: 9px; border: 1px solid var(--line); background: rgba(0,0,0,.18); margin-bottom: 12px; }
.modal-team .sw { width: 10px; height: 34px; background: linear-gradient(var(--tc), var(--ta)); }
.modal-team b { display: block; font-family: var(--display); font-size: 7px; line-height: 1.5; }
.modal-team span { display: block; color: var(--muted); font-size: 7px; margin-top: 4px; }
.modal-rider { display: flex; align-items: center; gap: 10px; width: 100%; padding: 10px; margin-top: 7px; border: 1px solid var(--line); background: #0d0f19; text-align: left; }
.modal-rider:hover { border-color: var(--lime); background: rgba(216,255,62,.05); }
.modal-rider .rh { width: 40px; height: 40px; display: grid; place-items: center; background: color-mix(in srgb, var(--tc) 25%, #0b0c15); border: 1px solid color-mix(in srgb, var(--tc) 60%, #2d3147); }
.modal-rider .rh svg { width: 26px; height: 26px; }
.modal-rider .ri { flex: 1; }
.modal-rider .rn { display: block; font-size: 10px; font-weight: 700; }
.modal-rider .rm { display: block; color: var(--muted); font-size: 7px; margin-top: 3px; }
.modal-rider .ro { font-family: var(--display); font-size: 11px; color: var(--lime); }
.modal-foot { display: flex; gap: 8px; margin-top: 14px; }
.modal-foot .spacer { flex: 1; }
.modal-note { color: var(--muted); font-size: 8px; line-height: 1.6; }

#toast {
  position: fixed;
  left: 50%;
  bottom: calc(86px + var(--safe-b));
  transform: translate(-50%, 16px);
  z-index: 120;
  max-width: min(430px, calc(100vw - 28px));
  padding: 10px 14px;
  background: var(--lime);
  color: #101010;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: .3px;
  box-shadow: 5px 5px 0 #000;
  opacity: 0;
  pointer-events: none;
  transition: opacity .18s, transform .18s;
  text-align: center;
}
#toast.show { opacity: 1; transform: translate(-50%, 0); }
#toast.error { background: var(--red); color: #111; }

/* ---------- animations ---------- */
@keyframes fadeIn { to { opacity: 1; } }
@keyframes popIn { from { transform: scale(.96) translateY(8px); opacity: 0; } to { transform: none; opacity: 1; } }
@keyframes blink { 0%, 45% { opacity: 1; } 50%, 100% { opacity: .35; } }
.blink { animation: blink 1.2s steps(1) infinite; }
@keyframes slideUp { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: none; } }
.screen-enter { animation: slideUp .22s ease-out; }

/* ---------- responsive ---------- */
@media (max-width: 980px) {
  .team-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
